<script setup lang="ts">
import type { AdminGuideFormValues } from '~/composables/useAdminGuides'
type Source = { id: string; name: string }
type Cover = { storage_path: string; alt_text: string | null; credit_text: string | null } | null
const props = defineProps<{ initialValues: AdminGuideFormValues; sources: Source[]; cover: Cover; saving: boolean; successMessage?: string }>()
const emit = defineEmits<{ save: [payload: { values: AdminGuideFormValues; coverFile: File | null; viewAfterSave: boolean }] }>()
const form = reactive<AdminGuideFormValues>({ ...props.initialValues }); const coverFile = ref<File | null>(null); const validationError = ref('')
const submit = (viewAfterSave: boolean) => { validationError.value = ''; if (!form.title.trim() || !form.slug.trim()) { validationError.value = 'English title and slug are required.'; return }; if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(form.slug.trim())) { validationError.value = 'Use lowercase letters, numbers, and hyphens for the slug.'; return }; emit('save', { values: { ...form, slug: form.slug.trim().toLowerCase() }, coverFile: coverFile.value, viewAfterSave }) }
</script>
<template><form class="space-y-6" @submit.prevent="submit(false)"><p v-if="validationError" class="rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{{ validationError }}</p><p v-if="successMessage" class="rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-800">{{ successMessage }}</p><section class="rounded-xl border border-slate-200 bg-white p-4 shadow-sm sm:p-5"><h2 class="text-base font-semibold text-slate-900">Basic information</h2><div class="mt-4 grid gap-4 sm:grid-cols-2"><div><label for="guide-title" class="block text-sm font-medium text-slate-800">English title *</label><input id="guide-title" v-model="form.title" required maxlength="250" class="mt-1.5 w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm"></div><div><label for="guide-slug" class="block text-sm font-medium text-slate-800">Slug *</label><input id="guide-slug" v-model="form.slug" required placeholder="using-t-money" class="mt-1.5 w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm"><p class="mt-1 text-xs text-slate-500">Lowercase letters, numbers, and hyphens only.</p></div><div><label for="guide-type" class="block text-sm font-medium text-slate-800">Guide type</label><select id="guide-type" v-model="form.guideType" class="mt-1.5 w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm"><option value="arrival">Arrival</option><option value="transport">Transport</option><option value="payment">Payment</option><option value="sim">SIM / Mobile</option><option value="maps">Maps</option><option value="language">Language</option><option value="etiquette">Etiquette</option><option value="emergency">Emergency</option><option value="troubleshooting">Troubleshooting</option><option value="general">General</option></select></div><div><label for="guide-source" class="block text-sm font-medium text-slate-800">Source</label><select id="guide-source" v-model="form.sourceId" class="mt-1.5 w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm"><option value="">No source selected</option><option v-for="source in sources" :key="source.id" :value="source.id">{{ source.name }}</option></select></div></div></section><section class="rounded-xl border border-slate-200 bg-white p-4 shadow-sm sm:p-5"><h2 class="text-base font-semibold text-slate-900">English content</h2><div class="mt-4 space-y-4"><div><label for="guide-summary" class="block text-sm font-medium text-slate-800">Summary</label><textarea id="guide-summary" v-model="form.summary" rows="2" maxlength="500" class="mt-1.5 w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm" /></div><div><label for="guide-body" class="block text-sm font-medium text-slate-800">Body Markdown</label><textarea id="guide-body" v-model="form.bodyMarkdown" rows="14" class="mt-1.5 w-full rounded-lg border border-slate-300 px-3 py-2.5 font-mono text-sm leading-6" /></div></div></section><section class="rounded-xl border border-slate-200 bg-white p-4 shadow-sm sm:p-5"><h2 class="text-base font-semibold text-slate-900">Publishing</h2><div class="mt-4 grid gap-4 sm:grid-cols-2"><div><label for="guide-status" class="block text-sm font-medium text-slate-800">Status</label><select id="guide-status" v-model="form.status" class="mt-1.5 w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm"><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></div><div><label for="guide-verified" class="block text-sm font-medium text-slate-800">Last verified</label><input id="guide-verified" v-model="form.lastVerifiedAt" type="date" class="mt-1.5 w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm"></div></div><label class="mt-5 flex items-start gap-3 rounded-lg bg-slate-50 p-3 text-sm text-slate-700"><input v-model="form.featured" type="checkbox" class="mt-0.5 h-4 w-4"><span><strong class="font-semibold text-slate-900">Featured guide</strong><br>Featured guides may appear in prominent areas such as Korea Travel Essentials.</span></label></section><AdminPlaceCoverImageField v-model:alt-text="form.coverAltText" v-model:credit-text="form.coverCreditText" :cover="cover" @update:file="coverFile = $event" /><div class="flex flex-wrap items-center justify-between gap-3 border-t border-slate-200 pt-5"><NuxtLink to="/admin/guides" class="rounded-lg px-3 py-2.5 text-sm font-medium text-slate-600 hover:bg-slate-100">Cancel</NuxtLink><div class="flex gap-3"><button type="submit" :disabled="saving" class="rounded-lg border border-slate-300 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 disabled:opacity-60">{{ saving ? 'Saving…' : 'Save' }}</button><button type="button" :disabled="saving" class="rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60" @click="submit(true)">{{ saving ? 'Saving…' : 'Save & view' }}</button></div></div></form></template>
